-- بيانات مقرر فيزياء 1 (المقرر 101، قيد الإعداد) — الجزء 2 من 2. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-phys1-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C5-L3-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تؤثر في جسم نقطي القوتان المبينتان في الشكل الآتي. ما مقدار القوة الموازنة لهما؟', null, '[{"src":"qimg/phys1/c5l3-o04-perp.svg","alt":"نقطة سوداء عند تقاطع محورين متقطعين +x إلى اليمين و+y إلى أعلى. يخرج منها سهمان أزرقان: سهم على المحور x إلى اليمين مكتوب عنده 12.0 N، وسهم على المحور y إلى أعلى مكتوب عنده 16.0 N."}]'::jsonb, '["28.0 N","4.0 N","20.0 N","10.6 N"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 146 — إيجاد القوة الموازنة'),
('mcq', 2, 'يؤثر في صندوق موضوع على سطح جليدي أفقي أملس قوتان أفقيتان: 12.0 N نحو الشرق و16.0 N نحو الشمال. ما اتجاه القوة التي تجعل الصندوق متزنًا؟', null, null, '["في اتجاه يصنع زاوية $53.1^\\circ$ شمال الشرق","في اتجاه يصنع زاوية $53.1^\\circ$ جنوب الغرب","في اتجاه يصنع زاوية $36.9^\\circ$ جنوب الغرب","في اتجاه يصنع زاوية $53.1^\\circ$ شمال الغرب"]'::jsonb, 'تطبيق', 'حساب اتجاه', 'متوسط', 'الكتاب ص 146 — إيجاد القوة الموازنة'),
('mcq', 3, 'تؤثر في جسم قوتان مقدار كلٍّ منهما 50.0 N، والزاوية بين اتجاهيهما $120^\circ$. ما مقدار القوة الموازنة لهما؟', null, null, '["50.0 N","100.0 N","86.6 N","0.0 N"]'::jsonb, 'فهم', 'حساب', 'سهل', 'الكتاب ص 146 — القوة الموازنة'),
('mcq', 4, 'تؤثر في حلقة ثلاث قوى أفقية كما في الشكل الآتي (منظر من أعلى). ما القوة الموازنة لهذه القوى؟', null, '[{"src":"qimg/phys1/c5l3-o04-ring.svg","alt":"حلقة عند تقاطع محورين متقطعين +x إلى اليمين و+y إلى أعلى، يخرج منها ثلاثة أسهم زرقاء: سهم طويل على المحور x إلى اليسار مكتوب عنده 128 N، وسهم قصير على المحور x إلى اليمين مكتوب عنده 64.0 N، وسهم إلى أعلى اليمين مكتوب عنده 122 N يصنع زاوية 30.0° مع الاتجاه الموجب للمحور x."}]'::jsonb, '["73.9 N في اتجاه يصنع $55.7^\\circ$ فوق الاتجاه الموجب للمحور x","314 N في اتجاه يصنع $30.0^\\circ$ أسفل الاتجاه السالب للمحور x","73.9 N في اتجاه يصنع $34.3^\\circ$ أسفل الاتجاه السالب للمحور x","73.9 N في اتجاه يصنع $55.7^\\circ$ أسفل الاتجاه السالب للمحور x"]'::jsonb, 'تطبيق', 'حساب من شكل', 'صعب', 'الكتاب ص 157 — التقويم 62'),
('mcq', 5, 'يُسحب ميزان نابضي بثلاثة حبال مربوطة في خطافه كما في الشكل الآتي، فيبقى الميزان ساكنًا. ما قراءة الميزان؟', null, '[{"src":"qimg/phys1/c5l3-o04-scale.svg","alt":"ميزان نابضي ذو قرص مدرج معلق من قضيب أفقي، وتحته خطاف تتصل به ثلاثة حبال تشد إلى أسفل، ممثلة بأسهم زرقاء: سهم رأسي إلى أسفل مكتوب عنده 150.0 N، وسهم إلى أسفل اليسار مكتوب عنده 75.0 N يصنع زاوية 27.0° مع الخط الرأسي، وسهم إلى أسفل اليمين مكتوب عنده 75.0 N يصنع زاوية 27.0° مع الخط الرأسي."}]'::jsonb, '["300.0 N","218.1 N","133.7 N","283.7 N"]'::jsonb, 'تطبيق', 'حساب من شكل', 'متوسط', 'الكتاب ص 157 — التقويم 67'),
('mcq', 6, 'تتدلى لوحة إعلانية ساكنةً من سلكين متماثلين، يصنع كلٌّ منهما زاوية $35.0^\circ$ فوق الأفقي، والشد في كل سلك 245 N. ما كتلة اللوحة؟', null, null, '["50.0 kg","28.7 kg","41.0 kg","14.3 kg"]'::jsonb, 'تحليل', 'حساب', 'صعب', 'الكتاب ص 151 — المراجعة 38'),
('mcq', 7, 'تؤثر في جسم قوتان: $\boldsymbol{F}_1$ مقدارها 25.0 N بزاوية $30.0^\circ$، و$\boldsymbol{F}_2$ مقدارها 40.0 N بزاوية $135.0^\circ$ (الزاويتان مقيستان من الاتجاه الموجب للمحور x عكس اتجاه دوران عقارب الساعة). ما مركّبتا القوة الثالثة التي تجعل الجسم متزنًا؟', null, null, '["المركّبة x $= -6.63\\ \\text{N}$ والمركّبة y $= +40.8\\ \\text{N}$","المركّبة x $= -40.8\\ \\text{N}$ والمركّبة y $= +6.63\\ \\text{N}$","المركّبة x $= +6.63\\ \\text{N}$ والمركّبة y $= -40.8\\ \\text{N}$","المركّبة x $= +6.63\\ \\text{N}$ والمركّبة y $= +40.8\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب بالمركّبات', 'متوسط', 'الكتاب ص 147، 157 — مسألة تحفيز، التقويم 65'),
('essay', 1, 'يتزن جسم تحت تأثير ثلاث قوى؛ القوتان الأولى والثانية مبينتان في الشكل الآتي: 33.0 N في اتجاه يصنع $90.0^\circ$ مع المحور x، و44.0 N في اتجاه يصنع $60.0^\circ$ مع المحور x. ما مقدار القوة الثالثة واتجاهها؟', null, '[{"src":"qimg/phys1/c5l3-o04-q65.svg","alt":"جسم نقطي عند تقاطع محورين متقطعين +x إلى اليمين و+y إلى أعلى. يخرج منه سهمان أزرقان: سهم على المحور y إلى أعلى مكتوب عنده 33.0 N، وسهم إلى أعلى اليمين مكتوب عنده 44.0 N يصنع زاوية 60.0° مع الاتجاه الموجب للمحور x."}]'::jsonb, null, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 157 — التقويم 65'),
('essay', 2, 'تؤثر في حلقة أربع قوى أفقية كما في الجدول الآتي (الزوايا مقيسة كما هو مبين). أوجد مقدار القوة الموازنة لهذه القوى واتجاهها.', '{"headers":["القوة","المقدار (N)","الاتجاه"],"rows":[["$\\boldsymbol{F}_1$","61.0","$17.0^\\circ$ شمال الشرق"],["$\\boldsymbol{F}_2$","38.0","$64.0^\\circ$ شمال الشرق"],["$\\boldsymbol{F}_3$","54.0","$8.0^\\circ$ غرب الشمال"],["$\\boldsymbol{F}_4$","93.0","$53.0^\\circ$ غرب الشمال"]]}'::jsonb, null, null, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 147 — مسألة تحفيز'),
('essay', 3, 'تُعلَّق لوحة كتلتها 15.0 kg بسلكين متماثلين، يصنع كلٌّ منهما زاوية $25.0^\circ$ مع الرأسي. (أ) احسب قوة الشد في كل سلك، مبيّنًا العلاقة بين قوتي الشد والقوة الموازنة لوزن اللوحة. (ب) حلّل: ماذا يحدث لقوة الشد في كل سلك إذا زادت الزاوية مع الرأسي مع بقاء الوزن ثابتًا؟ ولماذا؟', null, null, null, 'تحليل', 'حساب وتحليل', 'متوسط', 'الكتاب ص 151 — المراجعة 38 و40')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C5-L3-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'القوتان متعامدتان، فمقدار محصلتهما $R = \sqrt{(12.0)^2 + (16.0)^2} = 20.0\ \text{N}$، والقوة الموازنة تساوي المحصلة مقدارًا: 20.0 N (وتعاكسها اتجاهًا).', '["جُمع المقداران جمعًا جبريًا كأن القوتين في الاتجاه نفسه؛ والقوتان متعامدتان فتُجمعان بنظرية فيثاغورس.","طُرح المقداران كأن القوتين متعاكستان على خط واحد.","","طُرح مربّعا المقدارين: $\\sqrt{16.0^2 - 12.0^2}$؛ والصحيح جمع المربّعين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-20T17:53:29.977Z"}'::jsonb),
('mcq', 2, 1, 'زاوية المحصلة $\theta = \tan^{-1}\left(\frac{16.0}{12.0}\right) = 53.1^\circ$ شمال الشرق. القوة الموازنة تعاكس المحصلة تمامًا، فتكون في اتجاه يصنع زاوية $53.1^\circ$ جنوب الغرب (ومقدارها 20.0 N).', '["هذا اتجاه المحصلة نفسها؛ والموازنة تعاكسها.","","قُلبت النسبة في الظل: $\\tan^{-1}(12.0/16.0) = 36.9^\\circ$؛ والزاوية مع خط الشرق–الغرب هي $\\tan^{-1}(16.0/12.0)$.","عُكست المركّبة الشرقية فقط وبقيت المركّبة الشمالية؛ والموازنة تعاكس المركّبتين معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.978Z"}'::jsonb),
('mcq', 3, 0, 'باختيار المحور x على امتداد القوة الأولى: مركّبتا الأولى $(50.0,\ 0)$، ومركّبتا الثانية $(50.0\cos 120^\circ,\ 50.0\sin 120^\circ) = (-25.0,\ 43.3)$. المحصلة $(25.0,\ 43.3)$ ومقدارها $\sqrt{25.0^2 + 43.3^2} = 50.0\ \text{N}$؛ فالقوة الموازنة 50.0 N في عكس اتجاه المحصلة.', '["","جُمع المقداران جمعًا جبريًا كأن القوتين في الاتجاه نفسه، مع أن بينهما $120^\\circ$.","هذه محصلة قوتين مقدار كلٍّ منهما 50.0 N بينهما $60^\\circ$ لا $120^\\circ$.","المحصلة تنعدم فقط إذا كانت القوتان متعاكستين تمامًا (بينهما $180^\\circ$)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-20T17:53:29.978Z"}'::jsonb),
('mcq', 4, 3, '$\sum F_x = -128 + 64.0 + 122\cos 30.0^\circ = 41.7\ \text{N}$، و$\sum F_y = 122\sin 30.0^\circ = 61.0\ \text{N}$. المحصلة $R = \sqrt{41.7^2 + 61.0^2} = 73.9\ \text{N}$ بزاوية $\tan^{-1}(61.0/41.7) = 55.7^\circ$ فوق الاتجاه الموجب للمحور x. القوة الموازنة 73.9 N في الاتجاه المعاكس: $55.7^\circ$ أسفل الاتجاه السالب للمحور x.', '["هذه المحصلة نفسها؛ والموازنة تساويها مقدارًا وتعاكسها اتجاهًا.","جُمعت مقادير القوى الثلاث جمعًا جبريًا، ولا تُجمع القوى المختلفة الاتجاه بهذه الطريقة.","قُلبت النسبة في الظل: $\\tan^{-1}(41.7/61.0) = 34.3^\\circ$ هي الزاوية مع المحور y لا مع المحور x.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-20T17:53:29.978Z"}'::jsonb),
('mcq', 5, 3, 'المركّبتان الأفقيتان للحبلين المائلين متساويتان ومتعاكستان فتلغي إحداهما الأخرى. المركّبات الرأسية (إلى أسفل): $150.0 + 2(75.0\cos 27.0^\circ) = 150.0 + 133.7 = 283.7\ \text{N}$. يؤثر الميزان بالقوة الموازنة لهذه الحبال: 283.7 N إلى أعلى، وهي قراءته.', '["جُمعت مقادير القوى الثلاث مباشرة دون تحليل؛ والحبلان المائلان لا يسهمان في الاتجاه الرأسي إلا بمركّبتيهما.","استُعمل $\\sin 27.0^\\circ$ للمركّبة الرأسية، مع أن الزاوية مقيسة من الرأسي فالمركّبة الرأسية $75.0\\cos 27.0^\\circ$.","أُهمل الحبل الرأسي 150.0 N، وجُمعت المركّبتان الرأسيتان للحبلين المائلين فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-20T17:53:29.978Z"}'::jsonb),
('mcq', 6, 1, 'وزن اللوحة يساوي القوة الموازنة لقوتي الشد، أي مجموع مركّبتيهما الرأسيتين (الأفقيتان تلغي إحداهما الأخرى): $F_g = 2(245\sin 35.0^\circ) = 281\ \text{N}$، إذن $m = \frac{F_g}{g} = \frac{281}{9.80} = 28.7\ \text{kg}$.', '["جُمع مقدارا الشدين كاملين كأن السلكين رأسيان، وأُهملت زاوية الميل.","","استُعمل $\\cos 35.0^\\circ$ للمركّبة الرأسية، مع أن الزاوية مقيسة من الأفقي.","حُسبت المركّبة الرأسية لسلك واحد فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-20T17:53:29.978Z"}'::jsonb),
('mcq', 7, 2, '$\sum F_x = 25.0\cos 30.0^\circ + 40.0\cos 135.0^\circ = 21.65 - 28.28 = -6.63\ \text{N}$، و$\sum F_y = 25.0\sin 30.0^\circ + 40.0\sin 135.0^\circ = 12.5 + 28.28 = 40.8\ \text{N}$. القوة الموازنة تعاكس المحصلة، فمركّبتاها $+6.63\ \text{N}$ و$-40.8\ \text{N}$.', '["هاتان مركّبتا المحصلة نفسها؛ والقوة المطلوبة تعاكسها فتُعكس إشارتا المركّبتين.","بُدّل الجيب وجيب التمام: حُسبت المركّبة x بـ $\\sin$ والمركّبة y بـ $\\cos$.","","عُكست إشارة المركّبة x فقط؛ والموازنة تعاكس المحصلة في المركّبتين معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.978Z"}'::jsonb),
('essay', 1, null::int, null, null, 'القوة الثالثة هي القوة الموازنة للقوتين. مركّبتا المحصلة: $R_x = 33.0\cos 90.0^\circ + 44.0\cos 60.0^\circ = 0 + 22.0 = 22.0\ \text{N}$، و$R_y = 33.0 + 44.0\sin 60.0^\circ = 33.0 + 38.1 = 71.1\ \text{N}$. مقدار المحصلة $R = \sqrt{22.0^2 + 71.1^2} = 74.4\ \text{N}$، وزاويتها $\theta = \tan^{-1}\left(\frac{71.1}{22.0}\right) = 72.8^\circ$ فوق الاتجاه الموجب للمحور x. إذن القوة الثالثة 74.4 N في الاتجاه المعاكس: $72.8^\circ$ أسفل الاتجاه السالب للمحور x (أي بزاوية $252.8^\circ$ من الاتجاه الموجب للمحور x).', '["$R_x = 22.0\\ \\text{N}$","$R_y = 71.1\\ \\text{N}$","مقدار القوة الثالثة 74.4 N","اتجاهها $72.8^\\circ$ أسفل الاتجاه السالب للمحور x"]'::jsonb, '["$R_x = 44.0\\cos 60.0^\\circ = 22.0\\ \\text{N}$","$R_y = 33.0 + 44.0\\sin 60.0^\\circ = 71.1\\ \\text{N}$","$R = \\sqrt{(22.0)^2 + (71.1)^2} = 74.4\\ \\text{N}$","$\\theta = \\tan^{-1}(71.1/22.0) = 72.8^\\circ$","القوة الموازنة: 74.4 N بزاوية $72.8^\\circ$ أسفل الاتجاه السالب للمحور x"]'::jsonb, '[{"element":"المركّبة x","marks":1},{"element":"المركّبة y","marks":1},{"element":"المقدار","marks":1},{"element":"الاتجاه المعاكس للمحصلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المركّبتان والمقدار والاتجاه المعاكس كلها صحيحة"},{"level":"2–3 درجات","description":"المقدار صحيح مع خطأ في الاتجاه، أو خطأ في مركّبة واحدة"},{"level":"درجة واحدة","description":"مركّبة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إعطاء اتجاه المحصلة بدل عكسه","استعمال $\\sin 60.0^\\circ$ للمركّبة x","جمع المقدارين 33.0 و44.0 مباشرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-20T17:53:29.978Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نختار +x نحو الشرق و+y نحو الشمال، ونحسب الزاوية من الاتجاه الموجب للمحور x: $F_1$ عند $17.0^\circ$، $F_2$ عند $64.0^\circ$، $F_3$ عند $98.0^\circ$، $F_4$ عند $143.0^\circ$. المركّبات x: $58.3 + 16.7 - 7.5 - 74.3 = -6.8\ \text{N}$. المركّبات y: $17.8 + 34.2 + 53.5 + 56.0 = 161.4\ \text{N}$. المحصلة $R = \sqrt{(-6.8)^2 + (161.4)^2} = 162\ \text{N}$، واتجاهها يصنع $\tan^{-1}(6.8/161.4) = 2.4^\circ$ غرب الشمال. القوة الموازنة 162 N في الاتجاه المعاكس: $2.4^\circ$ شرق الجنوب.', '["تحويل الاتجاهات إلى زوايا من محور واحد","$\\sum F_x = -6.8\\ \\text{N}$","$\\sum F_y = 161.4\\ \\text{N}$","الموازنة 162 N بزاوية $2.4^\\circ$ شرق الجنوب"]'::jsonb, '["$F_{1x} = 61.0\\cos 17.0^\\circ = 58.3$، $F_{1y} = 61.0\\sin 17.0^\\circ = 17.8$","$F_{2x} = 38.0\\cos 64.0^\\circ = 16.7$، $F_{2y} = 38.0\\sin 64.0^\\circ = 34.2$","$F_{3x} = 54.0\\cos 98.0^\\circ = -7.5$، $F_{3y} = 54.0\\sin 98.0^\\circ = 53.5$","$F_{4x} = 93.0\\cos 143.0^\\circ = -74.3$، $F_{4y} = 93.0\\sin 143.0^\\circ = 56.0$","$\\sum F_x = -6.8\\ \\text{N}$، $\\sum F_y = 161.4\\ \\text{N}$، $R = 162\\ \\text{N}$","الموازنة: 162 N بزاوية $2.4^\\circ$ شرق الجنوب"]'::jsonb, '[{"element":"زوايا القوى من محور واحد","marks":1},{"element":"مجموع المركّبات x","marks":1},{"element":"مجموع المركّبات y","marks":1},{"element":"مقدار الموازنة واتجاهها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الزوايا والمجموعان والمقدار والاتجاه المعاكس صحيحة"},{"level":"2–3 درجات","description":"خطأ في مركّبة أو في الاتجاه النهائي مع منهجية صحيحة"},{"level":"درجة واحدة","description":"تحليل قوة أو قوتين تحليلًا صحيحًا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال $8.0^\\circ$ و$53.0^\\circ$ مباشرة من المحور x مع أنهما مقيستان من الشمال","إهمال الإشارة السالبة للمركّبات الغربية","إعطاء اتجاه المحصلة بدل اتجاه الموازنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-20T17:53:29.979Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) وزن اللوحة $F_g = mg = (15.0)(9.80) = 147\ \text{N}$ إلى أسفل. اللوحة متزنة، فمحصلة قوتي الشد هي القوة الموازنة للوزن: 147 N رأسيًا إلى أعلى. المركّبتان الأفقيتان للشدين متعاكستان ومتساويتان، والرأسيتان تحملان الوزن: $2F_{\text{T}}\cos 25.0^\circ = 147$، إذن $F_{\text{T}} = \frac{147}{2\cos 25.0^\circ} = 81.1\ \text{N}$. (ب) إذا زادت الزاوية مع الرأسي قلّ $\cos\theta$، ولأن المركّبتين الرأسيتين يجب أن تبقيا مساويتين للوزن نفسه، يجب أن يزداد الشد في كل سلك؛ وتزداد معه المركّبتان الأفقيتان اللتان تلغي إحداهما الأخرى.', '["الوزن 147 N","محصلة الشدين = الموازنة للوزن (147 N إلى أعلى)","$F_{\\text{T}} = 81.1\\ \\text{N}$","زيادة الزاوية تزيد الشد مع التعليل"]'::jsonb, '["$F_g = (15.0\\ \\text{kg})(9.80\\ \\text{m/s}^2) = 147\\ \\text{N}$","$2F_{\\text{T}}\\cos 25.0^\\circ - F_g = 0$","$F_{\\text{T}} = \\frac{147}{2(0.906)} = 81.1\\ \\text{N}$"]'::jsonb, '[{"element":"حساب الوزن","marks":1},{"element":"ربط الشدين بالقوة الموازنة","marks":1},{"element":"حساب الشد","marks":1},{"element":"تحليل أثر الزاوية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح للوزن والشد مع ربط بالموازنة وتحليل صحيح لأثر الزاوية"},{"level":"2–3 درجات","description":"حساب الشد صحيح مع تحليل ناقص، أو تحليل صحيح مع خطأ حسابي"},{"level":"درجة واحدة","description":"حساب الوزن فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال $\\sin 25.0^\\circ$ مع أن الزاوية مقيسة من الرأسي","نسيان أن الوزن يتوزع على سلكين","القول إن الشد يقل بزيادة الزاوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-20T17:53:29.979Z"}'::jsonb)
