from (values
('mcq', 1, 'ينزلق صندوق من السكون على السطح المائل الأملس المبين في الشكل الآتي. ما مقدار تسارعه؟', null, '[{"src":"qimg/phys1/c5l3-o05-smooth.svg","alt":"سطح مائل على شكل مثلث قائم، زاويته عند القاعدة اليسرى مكتوب عندها 30.0°، وعلى منتصف سطحه المائل صندوق. مكتوب أعلى الشكل «سطح أملس»."}]'::jsonb, '["8.49 m/s²","9.80 m/s²","5.66 m/s²","4.90 m/s²"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 147–149 — الحركة على مستوى مائل'),
('mcq', 2, 'ينزلق متزلج كتلته 55 kg إلى أسفل منحدر ثلجي كما في الشكل الآتي، ومعامل الاحتكاك الحركي بين الزلاجة والثلج 0.12. ما مقدار تسارعه؟', null, '[{"src":"qimg/phys1/c5l3-o05-skier.svg","alt":"سطح مائل زاويته عند القاعدة 30.0°، وعليه مستطيل يمثل المتزلج مكتوب عليه 55 kg. من المستطيل محوران متقطعان: +x موازٍ للسطح إلى أعلاه، و+y عمودي على السطح إلى الخارج. مكتوب أعلى الشكل μk = 0.12."}]'::jsonb, '["3.9 m/s²","4.9 m/s²","5.9 m/s²","7.9 m/s²"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 148–149 — المثال 6'),
('mcq', 3, 'يبدأ صندوق الانزلاق من السكون على سطح مائل أملس يميل $25.0^\circ$ على الأفقي. ما المسافة التي يقطعها على السطح خلال 2.00 s؟', null, null, '["16.6 m","17.8 m","8.28 m","19.6 m"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 147–149 — الحركة على مستوى مائل'),
('mcq', 4, 'يُراد دفع صخرة كتلتها 20.0 kg بسرعة ثابتة إلى أعلى سطح جبل يميل $30.0^\circ$ على الأفقي، بقوة موازية للسطح. إذا كان معامل الاحتكاك الحركي بين الصخرة والسطح 0.40، فما مقدار القوة اللازمة؟', null, null, '["98.0 N","166 N","176 N","30 N"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 157 — التقويم 68'),
('mcq', 5, 'ينزلق صندوق إلى أسفل سطح مائل خشن يميل $20.0^\circ$ على الأفقي بسرعة ثابتة. ما معامل الاحتكاك الحركي بين الصندوق والسطح؟', null, null, '["0.940","0.342","0.364","2.75"]'::jsonb, 'تحليل', 'حساب', 'سهل', 'الكتاب ص 150، 153 — المسألة 36، مختبر الفيزياء'),
('mcq', 6, 'ينزلق رجل كتلته 135 kg وابنه وكتلته 20 kg من السكون من قمة المنزلق المائل نفسه، ولهما معامل الاحتكاك الحركي نفسه. أيّهما يصل إلى أسفل المنزلق أولًا؟', null, null, '["يصلان معًا؛ لأن تسارعهما لا يعتمد على الكتلة","الرجل أولًا؛ لأن مركّبة وزنه الموازية للسطح أكبر","الابن أولًا؛ لأن قوة الاحتكاك المؤثرة فيه أصغر","الابن أولًا؛ لأن قصوره الذاتي أقل فيتسارع أكثر"]'::jsonb, 'تحليل', 'استدلال', 'صعب', 'الكتاب ص 158 — التقويم 72'),
('mcq', 7, 'دُفع صندوق إلى أعلى سطح مائل خشن يميل $25.0^\circ$ على الأفقي، ثم تُرك يتحرك وحده إلى أعلى السطح. إذا كان معامل الاحتكاك الحركي 0.20، فما مقدار تسارع الصندوق في أثناء صعوده؟', null, null, '["2.4 m/s²","4.1 m/s²","9.7 m/s²","5.9 m/s²"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 147–149 — الحركة على مستوى مائل'),
('essay', 1, 'تنزلق زلاجة كتلتها 48 kg من السكون إلى أسفل منحدر ثلجي يميل $22.0^\circ$ على الأفقي، ومعامل الاحتكاك الحركي بينها وبين الثلج 0.10. احسب: (أ) مقدار تسارع الزلاجة. (ب) سرعتها بعد 6.0 s من بدء الحركة.', null, null, null, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 148–149 — المثال 6'),
('essay', 2, 'يُسحب صندوق كتلته 63 kg بحبل موازٍ لسطح مائل يميل $14.0^\circ$ على الأفقي كما في الشكل الآتي، والشد في الحبل 512 N، ومعامل الاحتكاك الحركي بين الصندوق والسطح 0.27. ما مقدار تسارع الصندوق؟ وما اتجاهه؟', null, '[{"src":"qimg/phys1/c5l3-o05-pull.svg","alt":"سطح مائل منخفض الميل زاويته عند القاعدة 14.0°، وعليه صندوق مكتوب عليه 63 kg. يخرج من الصندوق سهم أزرق موازٍ للسطح إلى أعلاه مكتوب عنده FT و512 N. مكتوب أعلى الشكل μk = 0.27."}]'::jsonb, null, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 151 — المراجعة 39'),
('essay', 3, 'ينزلق متزلج كتلته 62 kg من السكون إلى أسفل منحدر يميل $37^\circ$ على الأفقي، ومعامل الاحتكاك الحركي 0.15، فيصل تسارعه إلى 4.7 m/s² وسرعته إلى 24 m/s بعد 5.0 s. لو ازداد الاحتكاك فجأة عند تلك اللحظة بحيث أصبحت القوة المحصلة المؤثرة فيه صفرًا: (أ) فما معامل الاحتكاك الحركي الجديد؟ (ب) صف حركة المتزلج بعد ذلك، وفسّر.', null, null, null, 'تحليل', 'حل وتفسير', 'متوسط', 'الكتاب ص 150 — المسألة 36')
