from (values
('mcq', 1, 3, 'السطح أملس، فالقوة المحصلة الموازية للسطح هي مركّبة الوزن الموازية $mg\sin\theta$، والقوة العمودية توازن المركّبة العمودية. إذن $a = \frac{mg\sin\theta}{m} = g\sin\theta = (9.80)(\sin 30.0^\circ) = 4.90\ \text{m/s}^2$ إلى أسفل السطح.', '["استُعمل $\\cos 30.0^\\circ$ بدل $\\sin 30.0^\\circ$؛ و$g\\cos\\theta$ هي مركّبة العمودية على السطح التي توازنها القوة العمودية.","هذا تسارع السقوط الحر الرأسي؛ أما على السطح المائل فلا يعمل إلا مركّبة الوزن الموازية للسطح.","استُعمل $\\tan 30.0^\\circ$؛ ولا يدخل الظل في حساب مركّبة الوزن الموازية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-20T17:53:29.979Z"}'::jsonb),
('mcq', 2, 0, 'في اتجاه y: $F_{\text{N}} = mg\cos\theta$. في اتجاه x (إلى أسفل السطح): $ma = mg\sin\theta - \mu_{\text{k}} mg\cos\theta$، إذن $a = g(\sin\theta - \mu_{\text{k}}\cos\theta) = 9.80(\sin 30.0^\circ - 0.12\cos 30.0^\circ) = 9.80(0.500 - 0.104) = 3.9\ \text{m/s}^2$.', '["","أُهملت قوة الاحتكاك؛ فهذا تسارع الانزلاق على سطح أملس.","أُضيف الاحتكاك إلى مركّبة الوزن بدل طرحه؛ والاحتكاك يعاكس حركة المتزلج إلى أسفل السطح.","بُدّل الجيب وجيب التمام: $g(\\cos\\theta - \\mu_{\\text{k}}\\sin\\theta)$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-20T17:53:29.979Z"}'::jsonb),
('mcq', 3, 2, '$a = g\sin\theta = 9.80\sin 25.0^\circ = 4.14\ \text{m/s}^2$ إلى أسفل السطح، و$d = v_i t + \frac{1}{2}at^2 = 0 + \frac{1}{2}(4.14)(2.00)^2 = 8.28\ \text{m}$.', '["أُهمل العامل $\\frac{1}{2}$ في معادلة الإزاحة.","استُعمل $g\\cos 25.0^\\circ$ تسارعًا بدل $g\\sin 25.0^\\circ$.","","استُعمل g كاملًا كأن الصندوق يسقط سقوطًا حرًا رأسيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-20T17:53:29.979Z"}'::jsonb),
('mcq', 4, 1, 'السرعة ثابتة فالمحصلة صفر. الصخرة تتحرك إلى أعلى السطح، فالاحتكاك إلى أسفله مع مركّبة الوزن الموازية: $F = mg\sin\theta + \mu_{\text{k}} mg\cos\theta = (20.0)(9.80)(0.500) + (0.40)(20.0)(9.80)(0.866) = 98.0 + 68 = 166\ \text{N}$.', '["هذه مركّبة الوزن الموازية للسطح فقط؛ وقد أُهمل الاحتكاك الذي يعيق حركة الصخرة إلى أعلى.","","حُسب الاحتكاك على أساس أن القوة العمودية تساوي الوزن ($\\mu_{\\text{k}} mg = 78.4\\ \\text{N}$)، والصحيح $F_{\\text{N}} = mg\\cos\\theta$.","جُعل الاحتكاك إلى أعلى السطح فطُرح: $98.0 - 68 = 30\\ \\text{N}$؛ والاحتكاك يعاكس الحركة، والصخرة تتحرك إلى أعلى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-20T17:53:29.980Z"}'::jsonb),
('mcq', 5, 2, 'السرعة ثابتة فالمحصلة صفر: $mg\sin\theta = \mu_{\text{k}} mg\cos\theta$، إذن $\mu_{\text{k}} = \tan\theta = \tan 20.0^\circ = 0.364$.', '["هذه قيمة $\\cos 20.0^\\circ$؛ ولم تُقسم مركّبة الوزن الموازية على العمودية.","هذه قيمة $\\sin 20.0^\\circ$؛ وكأن القوة العمودية تساوي الوزن.","","قُسمت المركّبة العمودية على الموازية فنتج $\\frac{1}{\\tan 20.0^\\circ}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-20T17:53:29.980Z"}'::jsonb),
('mcq', 6, 0, 'بتطبيق قانون نيوتن الثاني: $ma = mg\sin\theta - \mu_{\text{k}} mg\cos\theta$، فتُختصر الكتلة: $a = g(\sin\theta - \mu_{\text{k}}\cos\theta)$. فتسارعهما لا يعتمد على الكتلة؛ للاثنين التسارع نفسه، ويبدآن من السكون ويقطعان الإزاحة نفسها، فيصلان معًا.', '["","مركّبة وزن الرجل الموازية أكبر، لكن الاحتكاك عليه أكبر بالنسبة نفسها وكتلته أكبر؛ فالتسارع نفسه.","الاحتكاك على الابن أصغر، لكن مركّبة وزنه الموازية وكتلته أصغر بالنسبة نفسها؛ فالتسارع لا يتغير.","القصور الذاتي الأقل يقابله قوة محصلة أقل بالنسبة نفسها؛ فالتسارع لا يعتمد على الكتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-20T17:53:29.980Z"}'::jsonb),
('mcq', 7, 3, 'في أثناء الصعود يكون الاحتكاك إلى أسفل السطح (عكس الحركة) مع مركّبة الوزن الموازية، فكلتاهما تبطئان الصندوق: $a = g(\sin\theta + \mu_{\text{k}}\cos\theta) = 9.80(\sin 25.0^\circ + 0.20\cos 25.0^\circ) = 9.80(0.423 + 0.181) = 5.9\ \text{m/s}^2$ إلى أسفل السطح.', '["جُعل الاحتكاك إلى أعلى السطح فطُرح؛ وهو يكون إلى أعلى فقط عندما ينزلق الصندوق إلى أسفل.","أُهمل الاحتكاك وحُسبت مركّبة الوزن الموازية وحدها.","بُدّل الجيب وجيب التمام: $g(\\cos\\theta + \\mu_{\\text{k}}\\sin\\theta)$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-20T17:53:29.980Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نختار +x إلى أسفل السطح موازيًا له، و+y عموديًا عليه. في اتجاه y: $F_{\text{N}} = mg\cos\theta$. في اتجاه x: $ma = mg\sin\theta - \mu_{\text{k}} mg\cos\theta$، إذن $a = g(\sin\theta - \mu_{\text{k}}\cos\theta) = 9.80(\sin 22.0^\circ - 0.10\cos 22.0^\circ) = 9.80(0.375 - 0.093) = 2.8\ \text{m/s}^2$ إلى أسفل السطح. (ب) $v_f = v_i + at = 0 + (2.76)(6.0) = 17\ \text{m/s}$ إلى أسفل السطح.', '["$F_{\\text{N}} = mg\\cos\\theta$","$a = g(\\sin\\theta - \\mu_{\\text{k}}\\cos\\theta)$","$a = 2.8\\ \\text{m/s}^2$","$v_f = 17\\ \\text{m/s}$"]'::jsonb, '["$F_{\\text{N}} = mg\\cos 22.0^\\circ$","$a = g(\\sin\\theta - \\mu_{\\text{k}}\\cos\\theta) = 9.80(0.3746 - 0.0927) = 2.76\\ \\text{m/s}^2 \\approx 2.8\\ \\text{m/s}^2$","$v_f = v_i + at = 0 + (2.76)(6.0) = 16.6\\ \\text{m/s} \\approx 17\\ \\text{m/s}$"]'::jsonb, '[{"element":"القوة العمودية","marks":1},{"element":"علاقة التسارع","marks":1},{"element":"قيمة التسارع","marks":1},{"element":"السرعة النهائية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"القوة العمودية والتسارع والسرعة صحيحة بأرقام معنوية مناسبة"},{"level":"2–3 درجات","description":"التسارع صحيح والسرعة خاطئة، أو خطأ في الإشارة"},{"level":"درجة واحدة","description":"كتابة قانون نيوتن الثاني على المحور x فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال الاحتكاك","استعمال $F_{\\text{N}} = mg$","إضافة الاحتكاك إلى مركّبة الوزن الموازية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-20T17:53:29.980Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نختار +x إلى أعلى السطح و+y عموديًا عليه للخارج. في اتجاه y: $F_{\text{N}} = mg\cos\theta = (63)(9.80)\cos 14.0^\circ = 599\ \text{N}$، فقوة الاحتكاك $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}} = (0.27)(599) = 162\ \text{N}$ إلى أسفل السطح (عكس الحركة). مركّبة الوزن الموازية $mg\sin\theta = (63)(9.80)\sin 14.0^\circ = 149\ \text{N}$ إلى أسفل السطح. في اتجاه x: $ma = F_{\text{T}} - mg\sin\theta - f_{\text{k}} = 512 - 149 - 162 = 201\ \text{N}$، إذن $a = \frac{201}{63} = 3.2\ \text{m/s}^2$ إلى أعلى السطح.', '["$F_{\\text{N}} = 599\\ \\text{N}$","$f_{\\text{k}} = 162\\ \\text{N}$ إلى أسفل السطح","$mg\\sin\\theta = 149\\ \\text{N}$","$a = 3.2\\ \\text{m/s}^2$ إلى أعلى السطح"]'::jsonb, '["$F_{\\text{N}} = mg\\cos\\theta = 599\\ \\text{N}$","$f_{\\text{k}} = \\mu_{\\text{k}} F_{\\text{N}} = 161.7\\ \\text{N}$","$F_{gx} = -mg\\sin\\theta = -149.4\\ \\text{N}$","$F_{\\text{المحصلة}\\,x} = 512 - 149.4 - 161.7 = 200.9\\ \\text{N}$","$a = \\frac{200.9}{63} = 3.2\\ \\text{m/s}^2$ في الاتجاه الموجب (إلى أعلى السطح)"]'::jsonb, '[{"element":"القوة العمودية والاحتكاك","marks":1},{"element":"مركّبة الوزن الموازية","marks":1},{"element":"القوة المحصلة على المحور x","marks":1},{"element":"التسارع واتجاهه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"كل القوى صحيحة الإشارة والتسارع واتجاهه صحيحان"},{"level":"2–3 درجات","description":"خطأ في إحدى القوى مع منهجية صحيحة"},{"level":"درجة واحدة","description":"حساب القوة العمودية أو مركّبة الوزن فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الاحتكاك إلى أعلى السطح","استعمال $F_{\\text{N}} = mg$","إهمال مركّبة الوزن الموازية للسطح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-20T17:53:29.981Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المحصلة الموازية للسطح صفر: $mg\sin\theta - \mu_{\text{k}} mg\cos\theta = 0$، إذن $\mu_{\text{k}} = \tan\theta = \tan 37^\circ = 0.75$. (ب) لأن المحصلة أصبحت صفرًا فالتسارع صفر، فيستمر المتزلج في الانزلاق إلى أسفل المنحدر بسرعة ثابتة تساوي 24 m/s (سرعته لحظة ازدياد الاحتكاك)؛ فهو متزن متحرك، ولا يتوقف لأن انعدام المحصلة لا يعني التوقف.', '["$mg\\sin\\theta = \\mu_{\\text{k}} mg\\cos\\theta$","$\\mu_{\\text{k}} = \\tan 37^\\circ = 0.75$","التسارع صفر","يستمر بسرعة ثابتة 24 m/s ولا يتوقف"]'::jsonb, '["$F_{\\text{المحصلة}\\,x} = mg\\sin\\theta - \\mu_{\\text{k}} mg\\cos\\theta = 0$","$\\mu_{\\text{k}} = \\frac{\\sin\\theta}{\\cos\\theta} = \\tan 37^\\circ = 0.75$"]'::jsonb, '[{"element":"شرط انعدام المحصلة","marks":1},{"element":"قيمة المعامل","marks":1},{"element":"التسارع صفر","marks":1},{"element":"وصف الحركة بسرعة ثابتة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المعامل صحيح ووصف الحركة صحيح مع التعليل"},{"level":"2–3 درجات","description":"المعامل صحيح ووصف الحركة ناقص أو خاطئ"},{"level":"درجة واحدة","description":"كتابة شرط انعدام المحصلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المتزلج يتوقف فورًا","حساب $\\mu_{\\text{k}} = \\sin 37^\\circ$ أو $\\cos 37^\\circ$","إدخال الكتلة أو الزمن في حساب المعامل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-20T17:53:29.981Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C5-L3-O05') and x.type = v.type and x.number = v.number
