insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C5-L3-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يبين الشكل الآتي وزن صندوق $\boldsymbol{F}_{g}$ موضوع على سطح مائل زاويته $\theta$، ومركّبتي الوزن المتقطعتين 1 و2. ما مقدار المركّبة 1؟', null, '[{"src":"qimg/phys1/c5l3-o06-components.svg","alt":"سطح مائل زاويته عند القاعدة θ، وعليه صندوق. من مركز الصندوق سهم أزرق رأسي إلى أسفل مكتوب عنده Fg. ومن مركز الصندوق أيضًا سهمان أزرقان متقطعان: السهم المرقم 1 موازٍ للسطح إلى أسفله، والسهم المرقم 2 عمودي على السطح إلى داخله، وخطان رفيعان متقطعان يصلان رأسيهما برأس Fg فيكتمل مستطيل."}]'::jsonb, '["$F_g\\cos\\theta$","$F_g\\sin\\theta$","$F_g\\tan\\theta$","$\\frac{F_g}{\\sin\\theta}$"]'::jsonb, 'فهم', 'تفسير شكل', 'سهل', 'الكتاب ص 148 — المثال 5: مركّبتا الوزن لجسم على سطح مائل'),
('mcq', 2, 'ما مقدار مركّبة وزن الصندوق الموازية للسطح المائل المبين في الشكل الآتي؟', null, '[{"src":"qimg/phys1/c5l3-o06-box650.svg","alt":"سطح مائل زاويته عند القاعدة 40.0°، وعليه صندوق، ومن مركز الصندوق سهم أزرق رأسي إلى أسفل مكتوب عنده Fg = 650 N."}]'::jsonb, '["498 N","545 N","650 N","418 N"]'::jsonb, 'تطبيق', 'حساب من شكل', 'سهل', 'الكتاب ص 148 — المثال 5: مركّبتا الوزن لجسم على سطح مائل'),
('mcq', 3, 'تستقر كأس كتلتها 0.44 kg على طاولة رُفع أحد طرفيها فمالت بزاوية $15^\circ$ على الأفقي. ما مقدار مركّبة وزن الكأس العمودية على سطح الطاولة؟', null, null, '["4.2 N","1.1 N","0.43 N","4.3 N"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 150 — المسألة 30'),
('mcq', 4, 'يستقر صندوق وزنه 520 N على سطح مائل يصنع $35.0^\circ$ فوق الأفقي. اختير نظام إحداثي يكون فيه +x موازيًا للسطح إلى أعلاه، و+y عموديًا على السطح إلى الخارج. ما مركّبتا الوزن $F_{gx}$ و$F_{gy}$؟', null, null, '["$F_{gx} = +298\\ \\text{N}$ و$F_{gy} = -426\\ \\text{N}$","$F_{gx} = -426\\ \\text{N}$ و$F_{gy} = -298\\ \\text{N}$","$F_{gx} = -298\\ \\text{N}$ و$F_{gy} = -426\\ \\text{N}$","$F_{gx} = +298\\ \\text{N}$ و$F_{gy} = +426\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب بالإشارات', 'متوسط', 'الكتاب ص 148 — المثال 5: مركّبتا الوزن لجسم على سطح مائل'),
('mcq', 5, 'يجلس شخص كتلته 50.0 kg على كرسي مائل في عيادة أسنان، ومركّبة وزنه العمودية على مستوى مقعد الكرسي 449 N. ما الزاوية التي يميل بها المقعد على الأفقي؟', null, null, '["$23.6^\\circ$","$66.4^\\circ$","$42.5^\\circ$","$4.80^\\circ$"]'::jsonb, 'تحليل', 'حساب عكسي', 'صعب', 'الكتاب ص 150 — المسألة 31'),
('mcq', 6, 'ما الزاوية التي يجب أن يميل بها سطح مائل بالنسبة إلى المحور الرأسي حتى تكون مركّبة وزن حقيبة موضوعة عليه الموازية للسطح مساويةً لنصف مركّبة وزنها العمودية عليه؟', null, null, '["$26.6^\\circ$","$30.0^\\circ$","$60.0^\\circ$","$63.4^\\circ$"]'::jsonb, 'تحليل', 'حساب عكسي', 'صعب', 'الكتاب ص 150 — المسألة 33'),
('mcq', 7, 'يوضع كتاب على لوح، ثم تُزاد زاوية ميل اللوح على الأفقي تدريجيًا من $0^\circ$ نحو $90^\circ$. كيف تتغير مركّبتا وزن الكتاب؟', null, null, '["تقل المركّبة الموازية للسطح وتزداد العمودية عليه","تزداد المركّبة الموازية للسطح وتقل العمودية عليه","تزداد المركّبتان معًا","لا تتغيران؛ لأن وزن الكتاب ثابت"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 156 — التقويم 55 (b)'),
('essay', 1, 'يستقر صندوق وزنه 375 N على سطح مائل يصنع $28.0^\circ$ فوق الأفقي. اختر نظامًا إحداثيًا يكون فيه +x موازيًا للسطح إلى أعلاه، ثم أوجد مركّبتي وزن الصندوق الموازية للسطح والعمودية عليه مع إشارتيهما، وتحقق من منطقية الجواب.', null, null, null, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 148 — المثال 5: مركّبتا الوزن لجسم على سطح مائل'),
('essay', 2, 'في تجربة «أثر الزاوية» ثُبّت لوح خشبي ليشكّل سطحًا مائلًا بزاوية $45.0^\circ$، ثم عُلّق جسم كتلته 500 g بميزان نابضي وسُحب بالميزان موازيًا للسطح ببطء وبسرعة ثابتة إلى أعلاه، فكانت قراءة الميزان 4.10 N. (أ) احسب وزن الجسم. (ب) احسب مركّبة الوزن الموازية للسطح. (ج) قارن قراءة الميزان بهذه المركّبة، وفسّر الفرق.', null, null, null, 'تحليل', 'تحليل بيانات تجربة', 'متوسط', 'الكتاب ص 150 — تجربة أثر الزاوية'),
('essay', 3, 'يبين الشكل الآتي مخطط الجسم الحر لصندوق على سطح مائل زاويته $\theta$، والمحوران x وy مائلان بحيث يكون x موازيًا للسطح. (أ) أثبت أن الزاوية $\alpha$ بين $\boldsymbol{F}_{g}$ والاتجاه السالب للمحور y تساوي $\theta$. (ب) استنتج من ذلك مقداري مركّبتي الوزن. (ج) عند أي زاوية ميل تتساوى المركّبتان؟', null, '[{"src":"qimg/phys1/c5l3-o06-proof.svg","alt":"مخطط جسم حر: نقطة سوداء يمر بها محوران متقطعان مائلان؛ المحور +x يصعد إلى أعلى اليمين بزاوية صغيرة موازيًا للسطح المائل، والمحور +y عمودي عليه يصعد إلى أعلى اليسار. من النقطة سهم أزرق رأسي إلى أسفل مكتوب عنده Fg، وبينه وبين الجزء السفلي من المحور y قوس مكتوب عنده α. في أسفل يسار الشكل رسم صغير لسطح مائل مكتوب تحته «السطح المائل» وزاويته مع الأفقي θ، وهي مساوية لميل المحور x."}]'::jsonb, null, 'تحليل', 'إثبات واستنتاج', 'صعب', 'الكتاب ص 148، 150 — المثال 5، أثر الزاوية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C5-L3-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'المركّبة 1 موازية للسطح إلى أسفله. الزاوية بين $\boldsymbol{F}_{g}$ والعمودي على السطح تساوي $\theta$، فالمركّبة المقابلة لهذه الزاوية (الموازية للسطح) مقدارها $F_g\sin\theta$، أما المركّبة 2 (العمودية على السطح) فمقدارها $F_g\cos\theta$.', '["هذا مقدار المركّبة 2 العمودية على السطح؛ فالمركّبة المجاورة للزاوية $\\theta$ هي العمودية.","","الظل نسبة بين المركّبتين، وليس عاملًا لحساب إحداهما من الوزن.","هذا المقدار أكبر من الوزن، ولا يمكن أن تكون مركّبة متجه أكبر منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-20T17:53:29.981Z"}'::jsonb),
('mcq', 2, 3, '$F_{gx} = F_g\sin\theta = (650\ \text{N})\sin 40.0^\circ = 418\ \text{N}$ (إلى أسفل السطح).', '["هذه المركّبة العمودية على السطح $F_g\\cos 40.0^\\circ$؛ وقد بُدّل الجيب وجيب التمام.","استُعمل $F_g\\tan 40.0^\\circ$؛ ولا يدخل الظل في حساب المركّبة.","هذا الوزن كله؛ ولم يُحلل إلى مركّبتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-20T17:53:29.981Z"}'::jsonb),
('mcq', 3, 0, '$F_g = mg = (0.44)(9.80) = 4.31\ \text{N}$، والمركّبة العمودية على السطح $F_g\cos\theta = (4.31)\cos 15^\circ = 4.2\ \text{N}$.', '["","هذه المركّبة الموازية للسطح $F_g\\sin 15^\\circ$.","ضُربت الكتلة في $\\cos 15^\\circ$ مباشرة دون حساب الوزن ($mg$) أولًا.","هذا الوزن كله؛ والمركّبة العمودية أصغر منه لأن السطح مائل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-20T17:53:29.982Z"}'::jsonb),
('mcq', 4, 2, '$F_{gx} = -F_g\sin\theta = -(520)\sin 35.0^\circ = -298\ \text{N}$، و$F_{gy} = -F_g\cos\theta = -(520)\cos 35.0^\circ = -426\ \text{N}$. المركّبتان سالبتان لأنهما تشيران إلى أسفل السطح وإلى داخله، أي عكس الاتجاهين الموجبين.', '["المركّبة الموازية تشير إلى أسفل السطح، أي عكس +x، فهي سالبة.","بُدّل الجيب وجيب التمام: المركّبة الموازية $F_g\\sin\\theta$ لا $F_g\\cos\\theta$.","","المركّبتان تشيران عكس الاتجاهين الموجبين المختارين، فإشارتاهما سالبتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-20T17:53:29.983Z"}'::jsonb),
('mcq', 5, 0, '$F_g = mg = (50.0)(9.80) = 490\ \text{N}$. المركّبة العمودية $F_g\cos\theta = 449\ \text{N}$، إذن $\cos\theta = \frac{449}{490} = 0.916$، و$\theta = 23.6^\circ$.', '["","استُعملت علاقة الجيب: $\\sin\\theta = \\frac{449}{490}$؛ والجيب يخص المركّبة الموازية لا العمودية.","استُعمل الظل: $\\tan\\theta = \\frac{449}{490}$؛ والظل نسبة المركّبة الموازية إلى العمودية لا العمودية إلى الوزن.","جُمع مقدارا المركّبتين جمعًا جبريًا كأن مجموعهما يساوي الوزن، فاعتُبرت المركّبة الموازية $490 - 449 = 41\\ \\text{N}$ ثم $\\sin\\theta = \\frac{41}{490}$؛ والمركّبتان متعامدتان فلا تُجمعان جمعًا جبريًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-20T17:53:29.983Z"}'::jsonb),
('mcq', 6, 3, '$F_g\sin\theta = \frac{1}{2}F_g\cos\theta$، إذن $\tan\theta = 0.500$ و$\theta = 26.6^\circ$ بالنسبة إلى الأفقي. والمطلوب الزاوية بالنسبة إلى الرأسي: $90^\circ - 26.6^\circ = 63.4^\circ$.', '["هذه زاوية الميل بالنسبة إلى الأفقي؛ والسؤال عن الزاوية مع الرأسي.","جُعل $\\sin\\theta = 0.5$ بمقارنة المركّبة الموازية بنصف الوزن، لا بنصف المركّبة العمودية.","جُعل $\\cos\\theta = 0.5$ أو أُخذ متمم $30.0^\\circ$؛ والعلاقة الصحيحة $\\tan\\theta = 0.5$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-20T17:53:29.983Z"}'::jsonb),
('mcq', 7, 1, 'المركّبة الموازية $F_g\sin\theta$ تزداد من صفر (عند $0^\circ$) إلى $F_g$ (عند $90^\circ$)، والعمودية $F_g\cos\theta$ تقل من $F_g$ إلى صفر.', '["العكس هو الصحيح؛ فعند $0^\\circ$ تكون المركّبة الموازية صفرًا والعمودية مساوية للوزن.","","لا يمكن أن تزدادا معًا؛ فمجموع مربّعيهما يساوي مربّع الوزن الثابت.","الوزن ثابت لكن توزيعه بين المركّبتين يتغير بتغير الزاوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-20T17:53:29.984Z"}'::jsonb),
('essay', 1, null::int, null, null, 'في النظام الإحداثي المختار: +x موازٍ للسطح إلى أعلاه، و+y عمودي على السطح إلى الخارج. المركّبتان تشيران إلى أسفل السطح وإلى داخله فهما سالبتان: $F_{gx} = -F_g\sin\theta = -(375)\sin 28.0^\circ = -176\ \text{N}$، و$F_{gy} = -F_g\cos\theta = -(375)\cos 28.0^\circ = -331\ \text{N}$. التحقق: مقدار كل مركّبة أقل من الوزن 375 N، و$\sqrt{176^2 + 331^2} = 375\ \text{N}$.', '["وصف النظام الإحداثي (+x إلى أعلى السطح)","$F_{gx} = -176\\ \\text{N}$","$F_{gy} = -331\\ \\text{N}$","التحقق: كل مركّبة أقل من الوزن"]'::jsonb, '["$F_{gx} = -F_g\\sin\\theta = -(375\\ \\text{N})(0.469) = -176\\ \\text{N}$","$F_{gy} = -F_g\\cos\\theta = -(375\\ \\text{N})(0.883) = -331\\ \\text{N}$","$\\sqrt{(176)^2 + (331)^2} = 375\\ \\text{N}$"]'::jsonb, '[{"element":"النظام الإحداثي","marks":1},{"element":"المركّبة الموازية بإشارتها","marks":1},{"element":"المركّبة العمودية بإشارتها","marks":1},{"element":"التحقق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"النظام والمركّبتان بإشارتيهما والتحقق صحيحة"},{"level":"2–3 درجات","description":"المركّبتان صحيحتان مقدارًا مع خطأ في الإشارة أو نقص في التحقق"},{"level":"درجة واحدة","description":"مركّبة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل الجيب وجيب التمام","إعطاء المركّبتين إشارة موجبة","اختيار المحورين أفقيًا ورأسيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-20T17:53:29.984Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $F_g = mg = (0.500)(9.80) = 4.90\ \text{N}$. (ب) $F_g\sin\theta = (4.90)\sin 45.0^\circ = 3.46\ \text{N}$. (ج) قراءة الميزان (4.10 N) أكبر من المركّبة الموازية بمقدار $4.10 - 3.46 = 0.64\ \text{N}$. الجسم يتحرك بسرعة ثابتة فالمحصلة الموازية للسطح صفر، والميزان يوازن مركّبة الوزن الموازية وقوة الاحتكاك الحركي معًا؛ لأن الاحتكاك يعاكس حركة الجسم إلى أعلى فيكون إلى أسفل السطح: $F = F_g\sin\theta + f_{\text{k}}$، إذن $f_{\text{k}} \approx 0.64\ \text{N}$.', '["$F_g = 4.90\\ \\text{N}$","$F_g\\sin 45.0^\\circ = 3.46\\ \\text{N}$","القراءة أكبر بمقدار 0.64 N","الفرق يساوي الاحتكاك الحركي المتجه إلى أسفل السطح"]'::jsonb, '["$m = 500\\ \\text{g} = 0.500\\ \\text{kg}$، $F_g = (0.500)(9.80) = 4.90\\ \\text{N}$","$F_{gx} = 4.90\\sin 45.0^\\circ = 3.46\\ \\text{N}$","$f_{\\text{k}} = 4.10 - 3.46 = 0.64\\ \\text{N}$"]'::jsonb, '[{"element":"الوزن","marks":1},{"element":"المركّبة الموازية","marks":1},{"element":"المقارنة","marks":1},{"element":"التفسير بالاحتكاك واتجاهه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابان صحيحان مع مقارنة وتفسير صحيح لاتجاه الاحتكاك"},{"level":"2–3 درجات","description":"الحسابان صحيحان مع تفسير ناقص"},{"level":"درجة واحدة","description":"حساب الوزن فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تحويل الكتلة من g إلى kg","مقارنة القراءة بالوزن كله","القول إن الاحتكاك إلى أعلى السطح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-20T17:53:29.984Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المحور y عمودي على السطح، و$\boldsymbol{F}_{g}$ عمودي على الأفقي. الزاوية بين السطح والأفقي $\theta$؛ وعند تدوير خطين بالزاوية نفسها تبقى الزاوية بينهما ثابتة، فالزاوية بين العمودي على السطح (المحور −y) والعمودي على الأفقي (اتجاه $\boldsymbol{F}_{g}$) تساوي $\theta$ أيضًا، أي $\alpha$ = $\theta$. (ب) المركّبة على امتداد −y مجاورة للزاوية $\theta$: مقدارها $F_g\cos\theta$ (عمودية على السطح)، والمركّبة على امتداد −x مقابلة لها: مقدارها $F_g\sin\theta$ (موازية للسطح إلى أسفله). (ج) تتساوى المركّبتان عندما $F_g\sin\theta = F_g\cos\theta$، أي $\tan\theta = 1$، فتكون $\theta = 45^\circ$.', '["المحور y عمودي على السطح، و$\\boldsymbol{F}_{g}$ عمودي على الأفقي","الزاوية بينهما تساوي $\\theta$","الموازية $F_g\\sin\\theta$ والعمودية $F_g\\cos\\theta$","تتساويان عند $\\theta = 45^\\circ$"]'::jsonb, '["$\\alpha = \\theta$ لأن ضلعي كل منهما متعامدان على ضلعي الأخرى","$F_{gy} = -F_g\\cos\\theta$، $F_{gx} = -F_g\\sin\\theta$","$\\sin\\theta = \\cos\\theta \\Rightarrow \\tan\\theta = 1 \\Rightarrow \\theta = 45^\\circ$"]'::jsonb, '[{"element":"تعليل تعامد الضلعين","marks":1},{"element":"استنتاج $\\alpha$ = $\\theta$","marks":1},{"element":"المركّبتان","marks":1},{"element":"زاوية التساوي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إثبات معلل والمركّبتان وزاوية التساوي صحيحة"},{"level":"2–3 درجات","description":"المركّبتان وزاوية التساوي صحيحة مع إثبات ناقص"},{"level":"درجة واحدة","description":"المركّبتان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن $\\alpha$ تساوي متمم $\\theta$","تبديل الجيب وجيب التمام في المركّبتين","القول إن المركّبتين تتساويان عند $30^\\circ$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-20T17:53:29.984Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C5-L3-O06') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C5-L3-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما النظام الإحداثي الأنسب لتحليل حركة جسم على سطح مائل؟', null, null, '["المحور x موازٍ للسطح، والمحور y عمودي عليه","المحور x أفقي، والمحور y رأسي كما في الحركة على سطح أفقي","المحور x في اتجاه الحبل أو القوة المؤثرة أيًّا كان اتجاهها","لا فرق؛ فكل الأنظمة الإحداثية متساوية في سهولة الحل"]'::jsonb, 'فهم', 'اختيار إجراء', 'سهل', 'الكتاب ص 147، 150 — مخطط الجسم الحر على مستوى مائل واختيار النظام الإحداثي'),
('mcq', 2, 'ينزلق صندوق إلى أسفل سطح مائل خشن. أيّ المخططات المرقمة الآتية يمثل مخطط الجسم الحر الصحيح للصندوق؟ (الخط المتقطع يمثل اتجاه السطح)', null, '[{"src":"qimg/phys1/c5l3-o07-choices.svg","alt":"أربعة مخططات جسم حر مرقمة من 1 إلى 4، في كل منها نقطة سوداء يمر بها خط متقطع مائل يصعد إلى أعلى اليمين يمثل السطح، وأسهم زرقاء تخرج من النقطة. في الأربعة: سهم رأسي إلى أسفل Fg. المخطط 1: سهم FN عمودي على الخط المتقطع إلى أعلى اليسار، وسهم fk قصير موازٍ للخط إلى أسفل اليسار. المخطط 2: سهم FN عمودي على الخط إلى أعلى اليسار، وسهم fk موازٍ للخط إلى أعلى اليمين. المخطط 3: سهم FN رأسي إلى أعلى، وسهم fk موازٍ للخط إلى أعلى اليمين. المخطط 4: سهم FN عمودي على الخط إلى أعلى اليسار، وسهم fk موازٍ للخط إلى أعلى اليمين، وسهم إضافي F موازٍ للخط إلى أسفل اليسار."}]'::jsonb, '["المخطط 1","المخطط 4","المخطط 2","المخطط 3"]'::jsonb, 'تطبيق', 'تمييز مخطط', 'متوسط', 'الكتاب ص 147 — الشكل 5-13'),
('mcq', 3, 'عند اختيار المحور x موازيًا لسطح مائل والمحور y عموديًا عليه، أيّ القوى المؤثرة في جسم ينزلق على السطح المائل الخشن يلزم تحليلها إلى مركّبتين؟', null, null, '["القوة العمودية وحدها","قوة الوزن وحدها","قوة الاحتكاك وحدها","الوزن والقوة العمودية معًا"]'::jsonb, 'فهم', 'تفسير إجراء', 'سهل', 'الكتاب ص 150–151 — اختيار النظام الإحداثي'),
('mcq', 4, 'يُسحب صندوق بحبل موازٍ لسطح مائل خشن، فيتحرك إلى أعلى السطح كما في الشكل الآتي. عند رسم مخطط الجسم الحر للصندوق، ما اتجاه قوة الاحتكاك الحركي $\boldsymbol{f}_{\text{k}}$؟', null, '[{"src":"qimg/phys1/c5l3-o07-pull-up.svg","alt":"سطح مائل زاويته θ مكتوب عليه «سطح خشن»، وعليه صندوق. من الصندوق سهم أزرق موازٍ للسطح إلى أعلاه مكتوب عنده FT يمثل قوة الشد في الحبل، وفوق الصندوق سهم أحمر موازٍ للسطح إلى أعلاه مكتوب عنده v يمثل السرعة المتجهة."}]'::jsonb, '["موازية للسطح إلى أعلاه","عمودية على السطح إلى خارجه","رأسية إلى أعلى","موازية للسطح إلى أسفله"]'::jsonb, 'تطبيق', 'تحديد اتجاه قوة', 'سهل', 'الكتاب ص 147، 151 — الشكل 5-13، المراجعة 39'),
('mcq', 5, 'يستقر كتاب ساكنًا على سطح مائل خشن زاويته $\theta$. ما اتجاه قوة الاحتكاك السكوني $\boldsymbol{f}_{\text{s}}$ المؤثرة فيه، وما مقدارها؟', null, null, '["إلى أسفل السطح، ومقدارها $F_g\\sin\\theta$","إلى أعلى السطح، ومقدارها $F_g\\sin\\theta$","إلى أعلى السطح، ومقدارها $\\mu_{\\text{s}} F_g$","إلى أعلى السطح، ومقدارها $F_g\\cos\\theta$"]'::jsonb, 'تحليل', 'تحليل مخطط', 'صعب', 'الكتاب ص 150، 152 — السطح المائل، مختبر الفيزياء'),
('mcq', 6, 'يصعد شخص بسرعة ثابتة تلًّا يميل على الرأسي بزاوية $60^\circ$. عند رسم مخطط الجسم الحر له واختيار المحور x موازيًا لسطح التل، ما الزاوية بين وزنه والاتجاه السالب للمحور y؟', null, null, '["$60^\\circ$","$90^\\circ$","$30^\\circ$","$0^\\circ$"]'::jsonb, 'تطبيق', 'تحديد زاوية', 'متوسط', 'الكتاب ص 150 — المسألة 29'),
('mcq', 7, 'رسم طالب مخطط الجسم الحر لصندوق ساكن على سطح مائل خشن كما في الشكل الآتي. ما الخطأ في مخططه؟', null, '[{"src":"qimg/phys1/c5l3-o07-wrong.svg","alt":"سطح مائل زاويته θ وعليه صندوق، ومكتوب أعلى الشكل «الصندوق ساكن». من مركز الصندوق سهمان أزرقان متساويان في الطول: أحدهما رأسي إلى أعلى مكتوب عنده FN، والآخر رأسي إلى أسفل مكتوب عنده Fg. لا توجد أسهم أخرى."}]'::jsonb, '["القوة العمودية يجب أن تكون عمودية على السطح، وقد أغفل الاحتكاك السكوني إلى أعلى السطح","الوزن يجب أن يكون عموديًا على السطح المائل لا رأسيًا","يجب إضافة قوة موازية للسطح إلى أسفله تمثل ميل الصندوق إلى الانزلاق","لا خطأ فيه؛ فالقوتان متساويتان ومتعاكستان والصندوق ساكن"]'::jsonb, 'تحليل', 'تقويم مخطط', 'صعب', 'الكتاب ص 147، 150 — مخطط الجسم الحر والسطح المائل'),
('essay', 1, 'ينزلق صندوق إلى أسفل سطح مائل خشن زاويته $\theta$ كما في الشكل الآتي. (أ) حدّد النظام الإحداثي الأنسب، مبينًا اتجاهي +x و+y. (ب) صف مخطط الجسم الحر للصندوق: القوى المؤثرة واتجاه كلٍّ منها. (ج) اكتب مركّبتي كل قوة على المحورين.', null, '[{"src":"qimg/phys1/c5l3-o07-scene.svg","alt":"سطح مائل زاويته θ وعليه صندوق، ومكتوب أعلى الشكل «سطح خشن، والصندوق ينزلق إلى أسفل». لا توجد أسهم على الشكل."}]'::jsonb, null, 'تطبيق', 'وصف مخطط', 'متوسط', 'الكتاب ص 147، 150 — مخطط الجسم الحر على مستوى مائل واختيار النظام الإحداثي'),
('essay', 2, 'يصعد شخص بسرعة ثابتة تلًّا يميل على الرأسي بزاوية $60^\circ$. (أ) صف مخطط الجسم الحر لهذا الشخص مع النظام الإحداثي المناسب. (ب) لماذا تكون قوة الاحتكاك التي يؤثر بها سطح التل في حذائه إلى أعلى التل؟ (ج) عبّر عن مقدار كلٍّ من القوة العمودية وقوة الاحتكاك بدلالة وزنه $F_g$.', null, null, null, 'تطبيق', 'رسم وتحليل', 'متوسط', 'الكتاب ص 150 — المسألة 29'),
('essay', 3, 'قارن بين اختيار محورين أفقي ورأسي واختيار محورين مائلين (x موازٍ للسطح) لتحليل حركة صندوق ينزلق إلى أسفل سطح مائل خشن، من حيث: عدد القوى التي يلزم تحليلها، وعدد مركّبات التسارع. ثم بيّن أيّ الاختيارين أفضل ولماذا.', null, null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 150–151 — اختيار النظام الإحداثي')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C5-L3-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'تسارع الجسم على السطح المائل موازٍ للسطح، لذا يُختار المحور x موازيًا للسطح والمحور y عموديًا عليه؛ فيقع التسارع على محور واحد، وتقع القوة العمودية وقوة الاحتكاك على المحورين، ولا يحتاج إلى التحليل إلا الوزن.', '["","بهذا الاختيار يكون للتسارع مركّبتان، وتحتاج القوة العمودية والاحتكاك كلتاهما إلى التحليل، فيصعب الحل.","اتجاه القوة المؤثرة قد لا يوافق اتجاه التسارع؛ والمعيار أن يكون أحد المحورين في اتجاه التسارع الموازي للسطح.","كل الأنظمة تعطي النتيجة نفسها، لكنها ليست متساوية في السهولة؛ والنظام الموازي للسطح يقلل عدد القوى المحللة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-20T17:53:29.985Z"}'::jsonb),
('mcq', 2, 2, 'في المخطط 2: الوزن $\boldsymbol{F}_{g}$ رأسي إلى أسفل، والقوة العمودية $\boldsymbol{F}_{\text{N}}$ عمودية على السطح إلى خارجه، والاحتكاك الحركي $\boldsymbol{f}_{\text{k}}$ موازٍ للسطح إلى أعلاه (عكس حركة الصندوق إلى أسفل)، ولا توجد قوى أخرى.', '["في المخطط 1 الاحتكاك إلى أسفل السطح في اتجاه الحركة، والاحتكاك يعاكس الحركة.","في المخطط 4 أُضيفت قوة F إلى أسفل السطح لا يؤثر بها أي جسم؛ فميل الصندوق إلى الحركة تمثله مركّبة الوزن، ولا تُرسم قوة مستقلة للحركة.","","في المخطط 3 القوة العمودية رأسية، والقوة العمودية تكون دائمًا عمودية على السطح الملامس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-20T17:53:29.985Z"}'::jsonb),
('mcq', 3, 1, 'في هذا النظام تقع القوة العمودية على المحور y وقوة الاحتكاك على المحور x، أما الوزن فرأسي لا يقع على أي من المحورين؛ لذا يُحلل وحده إلى مركّبة موازية للسطح وأخرى عمودية عليه.', '["القوة العمودية عمودية على السطح، فهي تقع على المحور y تمامًا ولا تحتاج إلى تحليل.","","قوة الاحتكاك موازية للسطح، فهي تقع على المحور x تمامًا.","القوة العمودية تقع على المحور y؛ فالوزن وحده هو الذي يُحلل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.985Z"}'::jsonb),
('mcq', 4, 3, 'قوة الاحتكاك الحركي توازي سطحي التلامس وتعاكس اتجاه حركة الصندوق بالنسبة إلى السطح؛ والصندوق يتحرك إلى أعلى السطح، فالاحتكاك موازٍ للسطح إلى أسفله.', '["هذا اتجاه الحركة نفسه؛ والاحتكاك يعاكس الحركة.","هذا اتجاه القوة العمودية؛ أما الاحتكاك فموازٍ لسطح التلامس.","الاحتكاك لا يكون رأسيًا هنا؛ فهو موازٍ للسطح المائل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-20T17:53:29.985Z"}'::jsonb),
('mcq', 5, 1, 'الكتاب ساكن، فالمحصلة على المحور x (الموازي للسطح) صفر. مركّبة الوزن الموازية $F_g\sin\theta$ إلى أسفل السطح، فيجب أن يكون الاحتكاك السكوني إلى أعلى السطح ومقداره $f_{\text{s}} = F_g\sin\theta$.', '["لو كان الاحتكاك إلى أسفل لأضاف قوة إلى مركّبة الوزن الموازية وانزلق الكتاب؛ والكتاب ساكن.","","$\\mu_{\\text{s}} F_{\\text{N}}$ هي القيمة القصوى للاحتكاك السكوني، والوزن ليس القوة العمودية؛ والاحتكاك الفعلي يساوي ما يلزم للاتزان فقط.","$F_g\\cos\\theta$ مركّبة الوزن العمودية التي توازنها القوة العمودية لا الاحتكاك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-20T17:53:29.985Z"}'::jsonb),
('mcq', 6, 2, 'ميل التل على الرأسي $60^\circ$، أي إن ميله على الأفقي $90^\circ - 60^\circ = 30^\circ$. والزاوية بين الوزن والعمودي على السطح (−y) تساوي زاوية ميل السطح على الأفقي: $30^\circ$.', '["هذه زاوية ميل التل على الرأسي، لا على الأفقي؛ والزاوية بين الوزن و−y تساوي الميل على الأفقي.","الوزن ليس موازيًا للسطح ولا عموديًا على −y؛ فالزاوية بينهما تساوي زاوية الميل على الأفقي.","","الوزن رأسي، والمحور y مائل لأن السطح مائل؛ فلا ينطبقان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-20T17:53:29.985Z"}'::jsonb),
('mcq', 7, 0, 'القوة العمودية تكون دائمًا عمودية على سطح التلامس، لا رأسية. ولأن الصندوق ساكن على سطح مائل خشن فلا بد من احتكاك سكوني موازٍ للسطح إلى أعلاه يوازن مركّبة الوزن الموازية. المخطط الصحيح: $\boldsymbol{F}_{g}$ رأسي، و$\boldsymbol{F}_{\text{N}}$ عمودي على السطح، و$\boldsymbol{f}_{\text{s}}$ إلى أعلى السطح.', '["","الوزن رأسي دائمًا (نحو مركز الأرض) مهما كان ميل السطح؛ والذي يتغير هو مركّبتاه.","ميل الصندوق إلى الانزلاق تمثله مركّبة الوزن الموازية، ولا تُرسم قوة مستقلة لا يؤثر بها جسم.","على السطح المائل لا تكون القوة العمودية رأسية ولا مساوية للوزن، ولا يتزن الصندوق دون احتكاك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-20T17:53:29.986Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) المحور x موازٍ للسطح، ونختار +x إلى أسفل السطح في اتجاه الحركة والتسارع، والمحور y عمودي على السطح و+y إلى خارجه. (ب) ثلاث قوى تبدأ من الصندوق: الوزن $\boldsymbol{F}_{g}$ رأسي إلى أسفل، والقوة العمودية $\boldsymbol{F}_{\text{N}}$ عمودية على السطح إلى خارجه، والاحتكاك الحركي $\boldsymbol{f}_{\text{k}}$ موازٍ للسطح إلى أعلاه (عكس الحركة). (ج) الوزن: مركّبته x تساوي $+F_g\sin\theta$ ومركّبته y تساوي $-F_g\cos\theta$. القوة العمودية: x صفر، وy تساوي $+F_{\text{N}}$. الاحتكاك: x تساوي $-f_{\text{k}}$، وy صفر.', '["المحور x موازٍ للسطح وy عمودي عليه","ثلاث قوى بالاتجاهات الصحيحة","مركّبتا الوزن $F_g\\sin\\theta$ و$F_g\\cos\\theta$ بالإشارات الصحيحة","القوة العمودية والاحتكاك على المحورين دون تحليل"]'::jsonb, '[]'::jsonb, '[{"element":"النظام الإحداثي","marks":1},{"element":"القوى واتجاهاتها","marks":1},{"element":"مركّبتا الوزن","marks":1},{"element":"مركّبات القوتين الأخريين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"النظام والقوى الثلاث ومركّباتها بالإشارات الصحيحة"},{"level":"2–3 درجات","description":"القوى صحيحة مع خطأ في إشارة أو في تحليل الوزن"},{"level":"درجة واحدة","description":"ذكر القوى الثلاث دون نظام إحداثي أو مركّبات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم الاحتكاك في اتجاه الحركة","رسم القوة العمودية رأسية","إضافة قوة مستقلة باسم «قوة الحركة»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-20T17:53:29.986Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) ميل التل على الأفقي $30^\circ$. نختار +x موازيًا لسطح التل إلى أعلاه، و+y عموديًا عليه إلى الخارج. القوى (تبدأ من الشخص كنقطة): الوزن $\boldsymbol{F}_{g}$ رأسي إلى أسفل (يصنع $30^\circ$ مع −y)، والقوة العمودية $\boldsymbol{F}_{\text{N}}$ على امتداد +y، وقوة الاحتكاك السكوني $\boldsymbol{f}_{\text{s}}$ على امتداد +x. (ب) عند المشي يدفع الحذاء سطح التل إلى الخلف (إلى أسفل التل)، فيؤثر السطح في الحذاء بقوة احتكاك سكوني تمنع انزلاقه، اتجاهها إلى أعلى التل؛ وهي التي توازن مركّبة الوزن الموازية للسطح. (ج) السرعة ثابتة، فالمحصلة صفر: على المحور y: $F_{\text{N}} = F_g\cos 30^\circ = 0.866F_g$، وعلى المحور x: $f_{\text{s}} = F_g\sin 30^\circ = 0.500F_g$.', '["ميل التل على الأفقي $30^\\circ$ ونظام إحداثي موازٍ للسطح","ثلاث قوى: الوزن والقوة العمودية والاحتكاك إلى أعلى التل","تعليل اتجاه الاحتكاك","$F_{\\text{N}} = 0.866F_g$ و$f_{\\text{s}} = 0.500F_g$"]'::jsonb, '["زاوية الميل على الأفقي: $90^\\circ - 60^\\circ = 30^\\circ$","المحور y: $F_{\\text{N}} - F_g\\cos 30^\\circ = 0$","المحور x: $f_{\\text{s}} - F_g\\sin 30^\\circ = 0$"]'::jsonb, '[{"element":"زاوية الميل والنظام الإحداثي","marks":1},{"element":"القوى الثلاث","marks":1},{"element":"تعليل اتجاه الاحتكاك","marks":1},{"element":"مقدارا القوتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مخطط ونظام صحيحان مع تعليل الاحتكاك ومقدارين صحيحين"},{"level":"2–3 درجات","description":"مخطط صحيح مع خطأ في الزاوية أو في أحد المقدارين"},{"level":"درجة واحدة","description":"ذكر القوى دون اتجاهات صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال $60^\\circ$ زاوية ميل على الأفقي","رسم الاحتكاك إلى أسفل التل لأن الشخص يصعد","جعل القوة العمودية مساوية للوزن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-20T17:53:29.986Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في النظام الأفقي–الرأسي: الوزن يقع على المحور y، لكن القوة العمودية (عمودية على السطح المائل) وقوة الاحتكاك (موازية له) لا تقعان على أي محور، فيلزم تحليل قوتين، والتسارع الموازي للسطح له مركّبتان (أفقية ورأسية)، فنحصل على معادلتين تحتويان كلتاهما على مجاهيل. في النظام المائل: القوة العمودية على المحور y والاحتكاك على المحور x، فلا يُحلل إلا الوزن (قوة واحدة)، والتسارع كله على المحور x فتسارع المحور y صفر، فنحسب القوة العمودية مباشرة من المحور y ثم التسارع من المحور x. لذا النظام المائل أفضل لأنه يقلل عدد التحليلات ويضع التسارع على محور واحد، والنتيجة الفيزيائية نفسها في النظامين.', '["الأفقي–الرأسي: تحليل قوتين (العمودية والاحتكاك)","الأفقي–الرأسي: للتسارع مركّبتان","المائل: تحليل الوزن فقط، والتسارع على x وحده","الحكم: المائل أفضل مع التعليل، والنتيجة واحدة"]'::jsonb, '[]'::jsonb, '[{"element":"تحليل النظام الأفقي–الرأسي","marks":1},{"element":"مركّبتا التسارع فيه","marks":1},{"element":"تحليل النظام المائل","marks":1},{"element":"الحكم المعلل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة في البندين مع حكم معلل"},{"level":"2–3 درجات","description":"مقارنة في بند واحد مع حكم صحيح"},{"level":"درجة واحدة","description":"حكم صحيح دون مقارنة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النظام الأفقي يعطي نتيجة مختلفة","نسيان أن التسارع يصبح له مركّبتان في النظام الأفقي","الظن أن الوزن يحتاج إلى تحليل في النظام الأفقي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.986Z"}'::jsonb)
