('mcq', 2, 'ينزلق طفل كتلته 43 kg على السطح المائل المبين في الشكل الآتي في حديقة ألعاب. ما مقدار القوة العمودية بين الطفل والسطح المائل؟', null, '[{"src":"qimg/phys1/c5l3-o08-slide.svg","alt":"سطح مائل زاويته عند القاعدة 35°، وعليه صندوق صغير مكتوب عليه 43 kg يمثل الطفل."}]'::jsonb, '["$3.5 \\times 10^2\\ \\text{N}$","$4.2 \\times 10^2\\ \\text{N}$","$2.4 \\times 10^2\\ \\text{N}$","$5.1 \\times 10^2\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 150 — المسألة 32'),
('mcq', 3, 'وُضع صندوق على سطح مائل أملس يميل $60.0^\circ$ على الأفقي. ما العلاقة بين مقدار القوة العمودية المؤثرة فيه ووزنه؟', null, null, '["تساوي وزنه","تساوي ضعف وزنه","تساوي 0.866 من وزنه","تساوي نصف وزنه"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 149–150 — القوة العمودية على سطح مائل'),
('mcq', 4, 'يمثل المنحنى الآتي مقدار القوة العمودية المؤثرة في صندوق كتلته 10.0 kg موضوع على سطح مائل، بدلالة زاوية ميل السطح على الأفقي. عند أيّ زاوية ميل تساوي القوة العمودية نصف وزن الصندوق؟', null, '[{"src":"qimg/phys1/c5l3-o08-graph.svg","alt":"منحنى بياني محوره الأفقي زاوية الميل (°) من 0 إلى 90 بخطوة 10، ومحوره الرأسي القوة العمودية (N) من 0 إلى 100 بخطوة 10، مع شبكة. المنحنى أزرق متناقص يبدأ عند 98 N عند الزاوية 0، ويمر بنحو 85 N عند 30، ونحو 69 N عند 45، و49 N عند 60، ويصل إلى 0 عند 90."}]'::jsonb, '["$30^\\circ$","$60^\\circ$","$45^\\circ$","$90^\\circ$"]'::jsonb, 'فهم', 'قراءة منحنى', 'متوسط', 'الكتاب ص 149–150 — القوة العمودية على سطح مائل'),
('mcq', 5, 'ينزلق صندوق كتلته 12 kg إلى أسفل سطح مائل يميل $25^\circ$ على الأفقي، ومعامل الاحتكاك الحركي بينهما 0.20. ما مقدار قوة الاحتكاك الحركي المؤثرة في الصندوق؟', null, null, '["$24\\ \\text{N}$","$21\\ \\text{N}$","$9.9\\ \\text{N}$","$1.1 \\times 10^2\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 149 — المثال 6'),
('mcq', 6, 'متى يكون مقدار القوة العمودية المؤثرة في جسم موضوع على سطح مساويًا لوزن الجسم (بلا قوى أخرى عمودية على السطح)؟', null, null, '["عندما يكون السطح أفقيًا ($0^\\circ$)","عندما تكون زاوية الميل $45^\\circ$","عندما يكون السطح رأسيًا ($90^\\circ$)","عند أي زاوية إذا كان السطح أملس"]'::jsonb, 'فهم', 'استنتاج', 'سهل', 'الكتاب ص 149–150 — القوة العمودية على سطح مائل'),
('mcq', 7, 'صندوقان متماثلان ينزلقان على سطحين مائلين لهما معامل الاحتكاك الحركي نفسه؛ زاوية ميل الأول $20^\circ$ والثاني $40^\circ$. أيّ الصندوقين تؤثر فيه قوة احتكاك أكبر؟', null, null, '["الصندوق على السطح $40^\\circ$؛ لأن مركّبة وزنه الموازية للسطح أكبر","متساويتان؛ لأن الصندوقين متماثلان ولهما معامل الاحتكاك نفسه","الصندوق على السطح $40^\\circ$؛ لأنه ينزلق بسرعة أكبر","الصندوق على السطح $20^\\circ$؛ لأن القوة العمودية المؤثرة فيه أكبر"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 149–150 — القوة العمودية والاحتكاك على سطح مائل'),
('essay', 1, 'فسّر لماذا لا يساوي مقدار القوة العمودية بين جسم وسطح مائل وزن الجسم، ثم اشتق العلاقة $F_{\text{N}} = mg\cos\theta$ مستعملًا قانون نيوتن الثاني ونظامًا إحداثيًا مناسبًا.', null, null, null, 'فهم', 'تفسير واشتقاق', 'متوسط', 'الكتاب ص 149–150 — المثال 6 والقوة العمودية على سطح مائل'),
('essay', 2, 'يستقر صندوق كتلته 25.0 kg ساكنًا على سطح مائل يميل $30.0^\circ$ على الأفقي، ومعامل الاحتكاك السكوني بينهما 0.65. (أ) احسب القوة العمودية. (ب) احسب قوة الاحتكاك السكوني المؤثرة فعلًا في الصندوق. (ج) احسب القيمة القصوى للاحتكاك السكوني، وبيّن هل يبقى الصندوق ساكنًا. (د) ما الخطأ في استنتاج طالب افترض أن القوة العمودية تساوي الوزن؟', null, null, null, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 150، 159 — القوة العمودية، اختبار مقنن 8'),
('essay', 3, 'يبين الشكل الآتي صندوقين متماثلين كتلة كلٍّ منهما 5.00 kg: الأول على سطح أفقي، والثاني ساكن على سطح مائل يميل $30.0^\circ$ على الأفقي. قال طالب: «القوة العمودية على الصندوقين متساوية وتساوي 49.0 N؛ لأن لهما الوزن نفسه». قوّم عبارة الطالب بالحساب والتفسير.', null, '[{"src":"qimg/phys1/c5l3-o08-two.svg","alt":"شكلان مرقمان: في الشكل 1 صندوق مكتوب عليه 5.00 kg على سطح أفقي، وفي الشكل 2 صندوق مماثل مكتوب عليه 5.00 kg على سطح مائل زاويته مع الأفقي 30.0°."}]'::jsonb, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 150، 152 — القوة العمودية على سطح أفقي ومائل')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
