insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'القوة العمودية عمودية على السطح، ولا تسارع للجسم في اتجاهها (المحور y)؛ فهي توازن مركّبة الوزن العمودية على السطح فقط لا الوزن كله: $F_{\text{N}} = F_g\cos\theta = mg\cos\theta$، وهي أصغر من الوزن عندما يكون السطح مائلًا.', '["الاحتكاك موازٍ للسطح، فلا يؤثر في الاتجاه العمودي عليه؛ والقوة العمودية تساوي $mg\\cos\\theta$ سواء وُجد احتكاك أم لم يوجد.","الوزن $mg$ لا يتغير بميل السطح؛ الذي يتغير هو مركّبتاه.","","القوة العمودية عمودية على السطح المائل وليست رأسية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-20T17:53:29.987Z"}'::jsonb),
('mcq', 2, 0, '$F_{\text{N}} = mg\cos\theta = (43)(9.80)\cos 35^\circ = 345\ \text{N} \approx 3.5 \times 10^2\ \text{N}$.', '["","هذا وزن الطفل $mg = 421\\ \\text{N}$؛ وقد افتُرض خطأً أن القوة العمودية تساوي الوزن.","هذه مركّبة الوزن الموازية للسطح $mg\\sin 35^\\circ$؛ وقد بُدّل الجيب وجيب التمام.","قُسم الوزن على $\\cos 35^\\circ$ بدل ضربه فيه؛ فالقوة العمودية لا تكون أكبر من الوزن هنا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-20T17:53:29.987Z"}'::jsonb),
('mcq', 3, 3, '$F_{\text{N}} = F_g\cos\theta = F_g\cos 60.0^\circ = 0.500F_g$؛ أي نصف الوزن.', '["القوة العمودية تساوي الوزن على السطح الأفقي فقط.","قُسم الوزن على $\\cos 60.0^\\circ$ بدل ضربه فيه.","هذه قيمة $\\sin 60.0^\\circ$؛ وهي نسبة المركّبة الموازية للسطح إلى الوزن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-20T17:53:29.987Z"}'::jsonb),
('mcq', 4, 1, 'وزن الصندوق $mg = (10.0)(9.80) = 98.0\ \text{N}$، وهو قيمة المنحنى عند $0^\circ$. نصف الوزن 49.0 N، ويقطع المنحنى هذه القيمة عند $60^\circ$؛ لأن $F_{\text{N}} = mg\cos\theta$ و$\cos 60^\circ = 0.500$.', '["عند $30^\\circ$ تكون القوة العمودية نحو 85 N ($98.0\\cos 30^\\circ$)، لا 49.0 N؛ فهذه الزاوية تجعل المركّبة الموازية نصف الوزن.","","عند $45^\\circ$ تكون القوة العمودية نحو 69 N؛ فالعلاقة جيب تمام لا خطية.","عند $90^\\circ$ تنعدم القوة العمودية (سطح رأسي)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-20T17:53:29.987Z"}'::jsonb),
('mcq', 5, 1, '$F_{\text{N}} = mg\cos\theta = (12)(9.80)\cos 25^\circ = 107\ \text{N}$، و$f_{\text{k}} = \mu_{\text{k}} F_{\text{N}} = (0.20)(107) = 21\ \text{N}$.', '["استُعملت القوة العمودية مساوية للوزن: $(0.20)(12)(9.80) = 24\\ \\text{N}$؛ والقوة العمودية على السطح المائل $mg\\cos\\theta$.","","استُعمل $\\sin 25^\\circ$ بدل $\\cos 25^\\circ$ في حساب القوة العمودية.","هذه القوة العمودية نفسها ($mg\\cos 25^\\circ \\approx 107\\ \\text{N}$)؛ ولم تُضرب في معامل الاحتكاك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-20T17:53:29.987Z"}'::jsonb),
('mcq', 6, 0, '$F_{\text{N}} = mg\cos\theta$، وتكون $F_{\text{N}} = mg$ عندما $\cos\theta = 1$، أي $\theta = 0^\circ$ (سطح أفقي).', '["","عند $45^\\circ$ تتساوى المركّبتان الموازية والعمودية، و$F_{\\text{N}} = 0.707mg$.","على السطح الرأسي تنعدم القوة العمودية الناتجة عن الوزن.","نعومة السطح تلغي الاحتكاك ولا تغير القوة العمودية؛ فهي $mg\\cos\\theta$ في الحالتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-20T17:53:29.988Z"}'::jsonb),
('mcq', 7, 3, '$f_{\text{k}} = \mu_{\text{k}} F_{\text{N}} = \mu_{\text{k}} mg\cos\theta$. لأن $\cos 20^\circ = 0.940$ أكبر من $\cos 40^\circ = 0.766$، فالقوة العمودية والاحتكاك على السطح $20^\circ$ أكبر.', '["مركّبة الوزن الموازية لا تحدد الاحتكاك الحركي؛ فهو يتناسب مع القوة العمودية، وهي أصغر عند $40^\\circ$.","الاحتكاك يعتمد على القوة العمودية أيضًا، والقوة العمودية تختلف باختلاف زاوية الميل.","الاحتكاك الحركي لا يعتمد على السرعة، بل على المعامل والقوة العمودية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-20T17:53:29.988Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نختار المحور x موازيًا للسطح والمحور y عموديًا عليه. في هذا النظام تقع القوة العمودية على المحور y، أما الوزن فلا يقع على أي محور، فيُحلل إلى مركّبة موازية للسطح $F_g\sin\theta$ ومركّبة عمودية عليه $F_g\cos\theta$. الجسم لا يتحرك في اتجاه عمودي على السطح، فتسارعه على المحور y صفر: $F_{\text{المحصلة}\,y} = ma_y = 0$، أي $F_{\text{N}} - F_{gy} = 0$، إذن $F_{\text{N}} = F_g\cos\theta = mg\cos\theta$. فالقوة العمودية توازن مركّبة الوزن العمودية فقط، ولأن $\cos\theta < 1$ للسطح المائل فهي أصغر من الوزن، ولا تساويه إلا على السطح الأفقي ($\theta = 0$).', '["اختيار محورين موازٍ وعمودي على السطح","تحليل الوزن إلى مركّبتين","$a_y = 0$ فتكون $F_{\\text{N}} - F_g\\cos\\theta = 0$","$F_{\\text{N}} = mg\\cos\\theta$ أصغر من الوزن لأن $\\cos\\theta < 1$"]'::jsonb, '["$F_{\\text{المحصلة}\\,y} = ma_y = 0$","$F_{\\text{N}} - mg\\cos\\theta = 0$","$F_{\\text{N}} = mg\\cos\\theta$"]'::jsonb, '[{"element":"النظام الإحداثي","marks":1},{"element":"تحليل الوزن","marks":1},{"element":"تطبيق قانون نيوتن الثاني على y","marks":1},{"element":"النتيجة والتفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اشتقاق كامل مع تفسير سبب الاختلاف عن الوزن"},{"level":"2–3 درجات","description":"اشتقاق صحيح بلا تفسير، أو تفسير صحيح بلا اشتقاق كامل"},{"level":"درجة واحدة","description":"كتابة العلاقة النهائية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القوة العمودية توازن الوزن كله","كتابة $F_{\\text{N}} = mg\\sin\\theta$","إهمال أن التسارع على المحور y صفر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-20T17:53:29.988Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $F_{\text{N}} = mg\cos\theta = (25.0)(9.80)\cos 30.0^\circ = 212\ \text{N}$. (ب) الصندوق ساكن، فالاحتكاك السكوني يوازن مركّبة الوزن الموازية: $f_{\text{s}} = mg\sin\theta = (25.0)(9.80)(0.500) = 123\ \text{N}$ إلى أعلى السطح. (ج) $f_{\text{s, max}} = \mu_{\text{s}} F_{\text{N}} = (0.65)(212) = 1.4 \times 10^2\ \text{N}$، وهي أكبر من 123 N المطلوبة، فيبقى الصندوق ساكنًا. (د) لو افترض الطالب أن $F_{\text{N}} = mg = 245\ \text{N}$ لحصل على قيمة قصوى $(0.65)(245) = 1.6 \times 10^2\ \text{N}$، فيبالغ في تقدير الاحتكاك الممكن؛ لأن القوة العمودية على السطح المائل توازن مركّبة الوزن العمودية فقط ($mg\cos\theta$).', '["$F_{\\text{N}} = 212\\ \\text{N}$","$f_{\\text{s}} = 123\\ \\text{N}$ إلى أعلى السطح","$f_{\\text{s, max}} = 1.4 \\times 10^2\\ \\text{N}$ فيبقى ساكنًا","الخطأ: $F_{\\text{N}} = mg$ يعطي $1.6 \\times 10^2\\ \\text{N}$ مبالغًا فيها"]'::jsonb, '["$F_{\\text{N}} = (25.0)(9.80)(0.866) = 212\\ \\text{N}$","$f_{\\text{s}} = (25.0)(9.80)(0.500) = 122.5 \\approx 123\\ \\text{N}$","$f_{\\text{s, max}} = (0.65)(212) = 138 \\approx 1.4 \\times 10^2\\ \\text{N}$","$123\\ \\text{N} < 1.4 \\times 10^2\\ \\text{N}$، إذن يبقى ساكنًا"]'::jsonb, '[{"element":"القوة العمودية","marks":1},{"element":"الاحتكاك الفعلي","marks":1},{"element":"القيمة القصوى والحكم","marks":1},{"element":"تحليل خطأ الطالب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الأربعة صحيحة"},{"level":"2–3 درجات","description":"جزءان أو ثلاثة صحيحة"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار الاحتكاك السكوني الفعلي مساويًا لـ $\\mu_{\\text{s}} F_{\\text{N}}$ دائمًا","استعمال $F_{\\text{N}} = mg$","جعل الاحتكاك السكوني إلى أسفل السطح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-20T17:53:29.988Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة صحيحة للصندوق 1 فقط. الصندوق 1 (سطح أفقي): القوة العمودية رأسية وتوازن الوزن كله: $F_{\text{N}} = mg = (5.00)(9.80) = 49.0\ \text{N}$. الصندوق 2 (سطح مائل): القوة العمودية عمودية على السطح المائل، ولا تسارع في اتجاهها، فتوازن مركّبة الوزن العمودية فقط: $F_{\text{N}} = mg\cos 30.0^\circ = (49.0)(0.866) = 42.4\ \text{N}$، وهي أقل من الوزن. أما المركّبة الموازية ($24.5\ \text{N}$) فتوازنها قوة الاحتكاك السكوني لا القوة العمودية. فتساوي الوزنين لا يعني تساوي القوتين العموديتين؛ لأن القوة العمودية تعتمد على زاوية ميل السطح.', '["الحكم: العبارة خاطئة للصندوق 2","الصندوق 1: $F_{\\text{N}} = 49.0\\ \\text{N}$","الصندوق 2: $F_{\\text{N}} = 42.4\\ \\text{N}$","التفسير: القوة العمودية توازن المركّبة العمودية فقط"]'::jsonb, '["$F_g = (5.00)(9.80) = 49.0\\ \\text{N}$","الأفقي: $F_{\\text{N}} = 49.0\\ \\text{N}$","المائل: $F_{\\text{N}} = 49.0\\cos 30.0^\\circ = 42.4\\ \\text{N}$"]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"حساب الحالة الأفقية","marks":1},{"element":"حساب الحالة المائلة","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح وحسابان صحيحان وتفسير كامل"},{"level":"2–3 درجات","description":"حساب صحيح للحالة المائلة مع نقص في الحكم أو التفسير"},{"level":"درجة واحدة","description":"حكم صحيح دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول عبارة الطالب لأن الكتلتين متساويتان","حساب $F_{\\text{N}} = mg\\sin 30.0^\\circ = 24.5\\ \\text{N}$","نسيان دور الاحتكاك في موازنة المركّبة الموازية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-20T17:53:29.988Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
